  outcome?: "released" | "refunded" | "locked";
  fallbackLabel?: string;
  signerWalletOverride?: Awaited<ReturnType<typeof makeEphemeralCip30Wallet>>;
  datumBuyerOverride?: string;
  signedMessageOverride?: string;
